function windowPeaks(nums: number[], k: number): number[] {
  const out: number[] = [];
  for (let i = 0; i + k <= nums.length; i++) {
    let peak = nums[i];
    for (let j = i + 1; j < i + k; j++) peak = Math.max(peak, nums[j]);
    out.push(peak);
  }
  return out;
}

