function windowPeaks(nums: number[], k: number): number[] {
  const dq: number[] = []; // indexes; values decrease from head to the back
  let head = 0; // dq[head..] is live, so dropping the front is O(1)
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    if (head < dq.length && dq[head] <= i - k) head++; // front slid out
    while (dq.length > head && nums[dq[dq.length - 1]] <= nums[i]) dq.pop();
    dq.push(i);
    if (i >= k - 1) out.push(nums[dq[head]]);
  }
  return out;
}

